import{_ as t}from"./chunks/55043a22be53555f1832.C2OhGomQ.js";import{_ as o,o as a,c as i,a5 as n}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"Generalists Are Taking Over The World In The Digital Golden Ages","description":"","frontmatter":{"title":"Generalists Are Taking Over The World In The Digital Golden Ages","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/generalists-are-taking-over-the-world-in-the-digital-golden-ages.md","filePath":"en/letters/generalists-are-taking-over-the-world-in-the-digital-golden-ages.md"}'),r={name:"en/letters/generalists-are-taking-over-the-world-in-the-digital-golden-ages.md"};function s(l,e,h,p,u,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="generalists-are-taking-over-the-world-in-the-digital-golden-ages" tabindex="-1">Generalists Are Taking Over The World In The Digital Golden Ages <a class="header-anchor" href="#generalists-are-taking-over-the-world-in-the-digital-golden-ages" aria-label="Permalink to &quot;Generalists Are Taking Over The World In The Digital Golden Ages&quot;">​</a></h1><p>Dan Koe · 2023-05-13 · <a href="https://thedankoe.com/letters/generalists-are-taking-over-the-world-in-the-digital-golden-ages/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/generalists-are-taking-over-the-world-in-the-digital-golden-ages">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/y5wPua_gIfE?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I can’t help but wonder what artists, thinkers, and visionaries from the past would think of today’s world.</p><p>Would Alan Watts have a podcast?</p><p>Would Marcus Aurelius be Twitter famous?</p><p>Would Nietzsche do public speaking gigs about his New York Times bestseller?</p><p>Many people think they would “reject the world” and retire to the woods.</p><p>I would argue the exact opposite.</p><p>They would realize the raw power of the internet to spread their ideas to the world because humans have an innate drive to survive on more planes of existence than the physical.</p><p>But that’s not the main question on my mind.</p><p>I’m even more curious about today’s creators and how they will be remembered.</p><p>In a previous chat I had with <a href="https://twitter.com/iamjustincscott" target="_blank" rel="noreferrer">Justin C Scott</a> on our adventures in Greenville, South Carolina, he said something that stuck in my mind:</p><blockquote><p>The further removed an influential figure is from their time in history, the more mythical they become.</p></blockquote><blockquote><p>People stop perceiving them as a person and begin to see them as something more – as the arbiter of certain ideas, concepts, and philosophies.</p></blockquote><blockquote><p>They no longer live in the mind as someone who lived, but as an archetypal concept that feels as if they always were.</p></blockquote><p>In the time of Watts or Aurelius, their language was normal.</p><p>It probably wasn’t perceived as “deep” and “mysterious” as we often think it is.</p><p>It was just normal language.</p><p>As language evolved with culture and society, so did our perception of the teachings of old.</p><p>In 100 years from now, language will see substantial changes yet again, and today’s creators will be perceived as ancient artifacts.</p><p>Jordan Peterson, Joe Rogan, and Mr. Beast have all added their own thread to the cultural tapestry we continue to create.</p><p>But who will be in the next generation of creators?</p><p>I’ll let your imagination run wild to answer that question.</p><p>But I believe the landscape of public intellectuals will change as a whole.</p><p>Those we hold with high regard in our mind will diversify based on community and self-interest.</p><p>For every one Marcus Aurelius, there will be ten Joe Rogans.</p><p>But the Joe Rogans will all attract different types of followers based on their unique perspectives and personality.</p><p>They will all talk about the same thing via internet content, but the teachings will be vastly different due to their personal experience.</p><p>I’ve talked about the flipside of this in <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">The Future The Creator Economy.</a></p><p>Every creator will distill their expertise and attract a school of students that resonate with their teaching style.</p><p>Creators will evolve and their following will evolve with them.</p><p>This eliminates saturation in the creator economy because life isn’t saturated – and we are all making the transition into the digital society.</p><p><strong>Final Reminder</strong>: Solopreneur Sprints starts in 2 days and Digital Economics price doubles on that date. <a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">Check it out here</a> if you want to turn yourself into a fulfilling modern business.</p><h2 id="the-emerging-digital-society" tabindex="-1">The Emerging Digital Society <a class="header-anchor" href="#the-emerging-digital-society" aria-label="Permalink to &quot;The Emerging Digital Society&quot;">​</a></h2><p>Every single person that was remembered throughout time had one thing in common:</p><p>They were massive value creators.</p><p>They were fountainheads of knowledge, perspective, and insight.</p><p>They didn’t attempt to hold their thoughts in their finite headspace.</p><p>They wrote, spake, marketed, and sold the potent ideas that wove the web of their worldview.</p><p>This is why I recommend studying those 4 evergreen skills and pairing them with your personal interests to succeed in the new renaissance (see: <a href="https://thedankoe.com/the-1-million-dollar-skill-stack-learn-in-this-order/" target="_blank" rel="noreferrer">The $1 Million Dollar Skill Stack</a>).</p><p>Today’s world is different.</p><p>You have access to the internet.</p><p>The <em>internet.</em></p><p>The revolutionary invention that people see as normal parts of their lives.</p><p>The thing that distracts people from their potential but is the exact tool to escape surface-level living.</p><p>There is an emerging digital society.</p><p>The world wide web continues to develop in unforeseen ways and I see it as a next step in human evolution.</p><p>You’re either providing value online or you are putting it off until you are forced to for survival.</p><p>Over the past decade digital tools and aids have become such a part of our life that we didn’t even realize we are half-robot.</p><p>Of course, this comes with ramifications that the ancient masters warned about.</p><p>Mechanical and mindless living is the antagonist of a good life.</p><p>The internet must be used and it must not use you.</p><p>The power has shifted back into the hands of the individual. You have the ability to:</p><ol><li>Become highly skilled in any (valuable) topic you want in 3-6 months.</li><li>Form a high-level network that feeds you opportunities. This was impossible with prior barriers of physical location.</li><li>Attract an audience to your life’s work so you can get paid to do what you enjoy.</li></ol><p>Humans solve problems to evolve, and I genuinely believe we have problem-solved our way into the opportunity to do what we love at almost all times of the day (if you put in the work to do so).</p><h2 id="start-building-your-legacy-in-the-new-world" tabindex="-1">Start Building Your Legacy In The New World <a class="header-anchor" href="#start-building-your-legacy-in-the-new-world" aria-label="Permalink to &quot;Start Building Your Legacy In The New World&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>We are smack in the middle of a second renaissance and future thought leaders are emerging left and right.</p><p>This is not to be taken lightly.</p><p>I used to think the term “thought leader” was rather cringe. But it is arguably the most important endeavor one can take on.</p><p>To become a thought leader, you must first learn to lead yourself.</p><p>By leading yourself into the unknown, you expose yourself to:</p><ul><li>Novel ideas and perspectives</li><li>New potentials for your life (and others)</li><li>Skills that you must acquire to push further</li><li>Results you must get with those skills to maintain progress</li></ul><p>A thought leader will not be a thought leader for long if they do not build solutions that gets results for the occupants of society.</p><p>They must expand their mind to allow for thought to have further boundaries.</p><p>True thought can only go as far as the experience you have.</p><p>Here is how you begin to build your legacy in the new world:</p><h3 id="_1-identify-what-you-must-do" tabindex="-1">1) Identify What You Must Do <a class="header-anchor" href="#_1-identify-what-you-must-do" aria-label="Permalink to &quot;1) Identify What You Must Do&quot;">​</a></h3><p>There are infinite roads you can take that lead to the life you want.</p><p>But the first step is identifying the life you want so you can move in the right direction.</p><p>Dance between your desired future and despised future.</p><p>As you experience life:</p><ul><li>Be conscious and observant of those around you.</li><li>Take mental note of lives that you do not want to live.</li><li>Study the habits, patterns, and ideas of successful individuals.</li><li>Add brush strokes to the vision of your ideal future over time.</li></ul><p>It won’t be absolutely clear at first, and that’s okay. You have time.</p><h3 id="_2-solidify-a-vessel-for-actualizing-that-reality" tabindex="-1">2) Solidify A Vessel For Actualizing That Reality <a class="header-anchor" href="#_2-solidify-a-vessel-for-actualizing-that-reality" aria-label="Permalink to &quot;2) Solidify A Vessel For Actualizing That Reality&quot;">​</a></h3><p>This is where most people go wrong.</p><p>They dream and dream about doing incredible things but let it remain a dream. Why?</p><p>Because they don’t have a clear and certain path for making it work.</p><p>They don’t realize that nothing certain is worth having, and that the future is uncertain no matter what you do (this should be obvious).</p><p>You need skills and interests that you can practice and apply for life.</p><p>It truly doesn’t matter what skills or interests you choose.</p><p>If you are conscious of the problems that stand in the way of executing on your plan, the next step should be obvious. Don’t hide from it.</p><p>If starting a business is the path to the life you want, but you “don’t know how,” then learn how with the endless information online.</p><p>Ya… it will take some time.</p><p>If you realize that you need money to start that business you choose, but don’t have any, then you either have to start with a <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">lower cost business model</a> or get a higher-paying job (or experiment with budgeting techniques).</p><p>If you realize you can’t get a better job or don’t have the skill to start the low-cost business… answer the question yourself.</p><p>Too many people avoid doing what they “don’t want” even when it is standing in the way of what they want.</p><p>Change your perspective.</p><p>If it’s standing in the way of what you want, then you should want to do it.</p><p>Think.</p><p>Don’t get distracted.</p><p>Learn and apply the skills or interests that intrigue you most in alignment with your desired future.</p><p>When problems pop up, acquire the skills and interests necessary to overcome them.</p><p>Pretty simple.</p><p>No self-help prescription required.</p><p>You have a self-corrective compass called a mind.</p><p>Use it.</p><h3 id="_3-a-powerful-habit-formation-heuristic" tabindex="-1">3) A Powerful Habit Formation Heuristic <a class="header-anchor" href="#_3-a-powerful-habit-formation-heuristic" aria-label="Permalink to &quot;3) A Powerful Habit Formation Heuristic&quot;">​</a></h3><p><em>If you don’t know why you are doing something, why are you doing it?</em></p><p>Most people are unconscious as to <em>why</em> they are making 99% of the choices that they make.</p><p>Start questioning everything you do.</p><p>Everything.</p><p>If there is no conscious intention behind the action, stop doing it.</p><p>Why are you going out to drink and party?</p><p>I’m not telling you to stop. I’m telling you to have a reason.</p><p>I love the occasional party and can attribute much of my success to the conversations and people that I’ve met during those times.</p><p>But it’s usually used as a tactical reset after a period of extended intensity. It is a forced low that balances out the forced highs.</p><p>Back to questioning:</p><p>Why are you shoveling hot and spicy McChickens down your throat?</p><p>Again, I’m not telling you to stop.</p><p>I love a good ol’ Mcdonald’s trip, but it still does not derail me completely from my mental, physical, and financial health goals.</p><p>Why are you laying in bed instead of going to the gym?</p><p>Why are you going to work after complaining about how you hate it?</p><p>Because you have to?</p><p>Is that not wage slavery?</p><p>Do you even care?</p><p>Are you lying to yourself that it’s for another reason?</p><p>Are you going to do anything about it?</p><p>Or are you just going to keep doing the same things until the day you die?</p><p>When will you allow yourself to become fully conscious of the situation you’ve built yourself into?</p><p>The answers to these questions may shock you (if you’re honest with yourself).</p><p>There are no wrong actions, there are only actions without intention.</p><p>Lead. Your. Thoughts.</p><h3 id="_4-personal-distribution" tabindex="-1">4) Personal Distribution <a class="header-anchor" href="#_4-personal-distribution" aria-label="Permalink to &quot;4) Personal Distribution&quot;">​</a></h3><p>Building an audience, readership, or distribution isn’t only for online businesses.</p><p>It is the new way of life.</p><p>Building personal distribution is how you:</p><ul><li>Get a job without a job board</li><li>Sell a book without a publisher</li><li>Make music without a record label</li></ul><p>Be you, learn to persuade, and you get to skip ahead of those that rely on others for their success.</p><p>I’m in the process of self-publishing my book, <em>The Art Of Focus</em>, that has new plans to launch sooner than expected…</p><p>The average self-published book sells 250 copies (Googled statistic).</p><p>They make less than $1,000 a year.</p><p>I’ve almost guaranteed my book to be a best-seller simply because I’ve built an audience over the past 3-4 years.</p><p><em>And</em> all of the ideas are validated through my newsletters and social media engagement. I already know that people will love it because they’ve already shown that.</p><p>Same goes for any product I built that has a slight relation to what I talk about.</p><p>Since I’ve built distribution, I can build whatever I want.</p><p>I can start a gym, supplement line, apparel store, or even start producing music and get on a big stage when most producers will never see an audience of more than 100 people.</p><p>Fair? Maybe, maybe not.</p><p>Or it’s just the reality that people don’t learn the game before they try to win.</p><h3 id="_5-focus-on-perspective-development" tabindex="-1">5) Focus On Perspective Development <a class="header-anchor" href="#_5-focus-on-perspective-development" aria-label="Permalink to &quot;5) Focus On Perspective Development&quot;">​</a></h3><p>The biggest “shift” for me was realizing that audience building isn’t about the latest hacks and tactics.</p><p>It’s about novel perspectives – something that AI tools will never be able to do under the name of a human.</p><p>I don’t see how AI could take something like Ken Wilbers’ theory of everything, connect it to the creator economy, and distill “stages of creator development” from a place of experience <a href="https://thedankoe.com/the-one-person-business-roadmap-99-of-creators-make-this-mistake/" target="_blank" rel="noreferrer">like I did here</a>.</p><p>I’m assuming that AI can’t have insight and connect abstract patterns to its skills or interests.</p><p>There is a progression to this game, but you want to get to the point of contagious ideas that spread without your personal effort.</p><p>The creator economy is a game of mental warfare.</p><p>The more ideas you spread that form the identity and worldview of other individuals the more success will come to you.</p><p>If this doesn’t make sense to you, it won’t until you actually start building.</p><p>Good luck on your path, fellow Creator.</p><p>– Dan</p><p>P.S. Alright last one so I can close enrollment and not worry about promotion over the next few days.</p><p>Solopreneur Sprints starts in 2 days and Digital Economics price doubles on that date. <a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">Check it out here</a> if you want to turn yourself into a fulfilling modern business.</p>',153)])])}const m=o(r,[["render",s]]);export{y as __pageData,m as default};
